//! Profile modes (Beta `notes/local-docs/PLANO_MODOS.md`, `server/src/db/accounts.rs:66-84`).
//!
//! - **Hardcore**: a fresh career generated by the server, every save checked by the progression
//!   gates (`fi_saves::gates`), strikes on refusals.
//! - **Noob**: the player's own offline save as it is; only technical checks (shape, sizes, limits).
//!
//! The modes never meet (boards, friends, free roam), except the storefront, which is shared. A
//! Hardcore profile may become Noob; never the other way, because Noob progress was never checked.

use serde::{Deserialize, Serialize};
use std::fmt;
use std::str::FromStr;

/// A profile's mode. Wire strings: `"hardcore"`, `"noob"`.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum ProfileMode {
    /// Server-checked career.
    Hardcore,
    /// Own save, technical checks only.
    Noob,
}

/// A mode change the rules forbid, or an unknown mode string.
#[derive(Clone, Copy, Debug, PartialEq, Eq, thiserror::Error)]
pub enum ModeError {
    /// Noob to Hardcore (or a no-op change).
    #[error("a profile can only go from hardcore to noob")]
    ForbiddenChange,
    /// Not `hardcore` or `noob`.
    #[error("unknown profile mode")]
    Unknown,
}

impl ProfileMode {
    /// Stable wire string.
    pub const fn as_str(self) -> &'static str {
        match self {
            ProfileMode::Hardcore => "hardcore",
            ProfileMode::Noob => "noob",
        }
    }

    /// Whether saves of this mode go through the progression gates.
    pub const fn is_gated(self) -> bool {
        matches!(self, ProfileMode::Hardcore)
    }

    /// Validates a mode change (`POST /v2/profiles/{id}/mode`).
    pub fn change_to(self, to: ProfileMode) -> Result<ProfileMode, ModeError> {
        match (self, to) {
            (ProfileMode::Hardcore, ProfileMode::Noob) => Ok(ProfileMode::Noob),
            _ => Err(ModeError::ForbiddenChange),
        }
    }
}

impl FromStr for ProfileMode {
    type Err = ModeError;

    fn from_str(s: &str) -> Result<Self, ModeError> {
        match s {
            "hardcore" => Ok(ProfileMode::Hardcore),
            "noob" => Ok(ProfileMode::Noob),
            _ => Err(ModeError::Unknown),
        }
    }
}

impl fmt::Display for ProfileMode {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn only_hardcore_to_noob() {
        assert_eq!(
            ProfileMode::Hardcore.change_to(ProfileMode::Noob),
            Ok(ProfileMode::Noob)
        );
        assert_eq!(
            ProfileMode::Noob.change_to(ProfileMode::Hardcore),
            Err(ModeError::ForbiddenChange)
        );
        assert_eq!(
            ProfileMode::Noob.change_to(ProfileMode::Noob),
            Err(ModeError::ForbiddenChange)
        );
    }

    #[test]
    fn wire_strings_are_stable() {
        assert_eq!(
            serde_json::to_string(&ProfileMode::Hardcore).unwrap(),
            "\"hardcore\""
        );
        assert_eq!("noob".parse::<ProfileMode>(), Ok(ProfileMode::Noob));
        assert_eq!("Noob".parse::<ProfileMode>(), Err(ModeError::Unknown));
        assert!(ProfileMode::Hardcore.is_gated());
        assert!(!ProfileMode::Noob.is_gated());
    }
}
